    's3-model-version':el=>{const s=current();s.modelId=el.dataset.id;s.rigId=s.rigs.filter(r=>r.modelId===s.modelId).at(-1)?.id||null;s.animationId=motions(s)[0]?.id||null;s.renderSelection.movements=motions(s).map(a=>a.id);storage().step=1;persist();render();},
    's3-open-result':el=>{const s=current(),r=subject(s).results.find(r=>r.id===el.dataset.id);if(r)api.openResult(s.subject,r);},
