    box([0,1.25,0],[.58,.72,.32],colors.coat,0,0,hip.twist*rad*.3);
    box([0,1.86,.03],[.44,.43,.42],colors.skin,head.bend*rad*.4,head.spread*rad*.3,head.twist*rad*.6);
    box([0,2.07,0],[.49,.16,.45],colors.coat,head.bend*rad*.4,head.spread*rad*.3,head.twist*rad*.6);
