    if(!output){const x=W*c.pivotX/100,y=H*c.pivotY/100;ctx.strokeStyle='#fff8f4';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x-7,y);ctx.lineTo(x+7,y);ctx.moveTo(x,y-7);ctx.lineTo(x,y+7);ctx.stroke();ctx.strokeStyle='#e2dbd0';ctx.setLineDash([3,3]);ctx.strokeRect(W*.08,H*.04,W*.84,H*.92);ctx.setLineDash([]);}
