  function previewTiming(s){const a=currentMotion(s),count=s.camera.frames,fps=a?.settings.fps||8,duration=count/fps*1000,index=a?.settings.loop?Math.floor(tick*fps/1000)%count:Math.min(count-1,Math.floor(tick*fps/1000));return {a,count,fps,duration,index,phase:index/(a?.settings.loop?count:Math.max(1,count-1))};}
  function drawPreview(){const s=current(),can=$('#s3-preview');if(!s||!can)return;const t=previewTiming(s);drawMannequin(can,{camera:s.camera,rig:currentRig(s),animation:t.a,showRig:s.showRig,direction:s.previewDirection||'Sud'},t.phase);const status=$('#s3-preview-status');if(status)status.textContent=`${s.previewDirection||'Sud'} · ${s.camera.projection} · azimut ${Math.round(s.camera.azimuth)}° · élévation ${Math.round(s.camera.elevation)}° · ${t.a?t.a.name+' · frame '+(t.index+1)+' / '+t.count+' · '+t.fps+' i/s · '+(t.duration/1000).toFixed(2)+' s':'pose de repos'}`;}
  function stop(){clearInterval(timer);timer=null;playing=false;}
  function startTimer(){clearInterval(timer);let last=performance.now(),shown=-1;timer=setInterval(()=>{if(!$('#s3-preview')){stop();return;}const now=performance.now();tick+=now-last;last=now;const t=previewTiming(current());if(t.a&&!t.a.settings.loop&&tick>=t.duration){tick=t.duration-1;stop();render();return;}if(shown!==t.index){shown=t.index;drawPreview();}},16);}
  function syncCameraControls(){const c=current().camera;for(const key of ['azimuth','elevation','framing','targetY','pivotX','pivotY','preset'])document.querySelectorAll(`[name="s3-${key}"]`).forEach(el=>{el.value=typeof c[key]==='number'?Math.round(c[key]*100)/100:c[key];});}
  function afterRender(){
    const can=$('#s3-preview');if(!can)return;const s=current();
    // Contrôles communs ajoutés au même endroit sur les six étapes.
    can.insertAdjacentHTML('beforebegin',sselect('Direction à inspecter','previewDirection',subject(s).directions,s.previewDirection||'Sud'));
    const imageTools=$('[data-action="s3-retouch-image"]');if(imageTools&&s.image?.id)imageTools.insertAdjacentHTML('afterend',button('Reprendre son rendu retouché','s3-refresh-image'));
    const r=currentRig(s);if(storage().step===2&&r){const joint=$('[name="s3-joint"]');joint?.closest('.field').insertAdjacentHTML('beforebegin',field('Version du squelette',`<select name="s3-rigVersion">${s.rigs.filter(x=>x.modelId===s.modelId).map(x=>`<option value="${x.id}" ${r.id===x.id?'selected':''}>Squelette v${x.version} · ${currentModel(s)?.validated&&x.check&&x.validated===signature(x.adjustments)?'contrôlé':'à vérifier'}</option>`).join('')}</select>`));joint?.closest('.field').insertAdjacentHTML('afterend',button('Remettre cette articulation à zéro','s3-reset-joint'));}
    drawPreview();if(playing)startTimer();
    can.addEventListener('pointerdown',e=>{if(e.button!==0)return;const c=current().camera,start={x:e.clientX,y:e.clientY,a:c.azimuth,e:c.elevation};can.setPointerCapture(e.pointerId);const move=ev=>{c.azimuth=(start.a+(ev.clientX-start.x)*.65+720)%360;c.elevation=clamp(start.e+(ev.clientY-start.y)*.35,-10,90);c.preset='Personnalisée';syncCameraControls();drawPreview();};const end=()=>{can.removeEventListener('pointermove',move);can.removeEventListener('pointerup',end);can.removeEventListener('pointercancel',end);persist();render();};can.addEventListener('pointermove',move);can.addEventListener('pointerup',end);can.addEventListener('pointercancel',end);});
    can.addEventListener('wheel',e=>{e.preventDefault();current().camera.framing=clamp(current().camera.framing-e.deltaY*.001,1,2);persist();syncCameraControls();drawPreview();},{passive:false});
    can.addEventListener('keydown',e=>{const c=current().camera;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')c.azimuth=(c.azimuth+355)%360;if(e.key==='ArrowRight')c.azimuth=(c.azimuth+5)%360;if(e.key==='ArrowUp')c.elevation=clamp(c.elevation+5,-10,90);if(e.key==='ArrowDown')c.elevation=clamp(c.elevation-5,-10,90);c.preset='Personnalisée';persist();syncCameraControls();drawPreview();});
    document.querySelectorAll('[data-s3-pair][type="range"]').forEach(el=>el.addEventListener('change',()=>render()));
  }
  function galleryItems(){storage();return st().sources3D.flatMap(s=>s.models.map(m=>({r:{id:m.id,title:s.name+' · modèle v'+m.version,animated:false,frames:[],image:m.image?.url||api.image,provenance:m.profile+' · modèle simulé',source3DId:s.id,source3DModelId:m.id,revision:m.version,savedAt:m.date},s:null,type:'3D',role:'Source 3D',groupId:s.id,subjectId:s.subject,source3DId:s.id})));}
