  function consumptionRows(){storage();return st().source3DJobs.map(j=>({id:j.id,title:j.title,model:j.model,status:j.status,unit:'local',amount:null,label:'0 $ fournisseur · temps local non mesuré'}));}
  return {ouvrir,entry,views:{source3d:view},handlers,change,afterRender,beforeRender:()=>{clearInterval(timer);timer=null;},stop,galleryItems,openGallery,isSource:key=>(st().sources3D||[]).some(s=>s.id===key||s.models.some(m=>m.id===key)),jobsSection,consumptionRows,pendingJobs:()=>(st().source3DJobs||[]).filter(j=>j.status==='En attente').length,canRestore:()=>!!current()};
